package org.apache.commons.lang3;

import java.io.*;
import java.math.*;
import java.util.*;
import java.util.Random;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.mockito.Mockito.*;

public class RandomStringUtils_random_TriageGen1Test {

    @Test
    public void testRandom_CountZero() {
        String result = RandomStringUtils.random(0, 0, 0, true, true, null, new Random());
        assertEquals("", result);
    }

    @Test(expected = IllegalArgumentException.class)
    public void testRandom_CountNegative() {
        RandomStringUtils.random(-1, 0, 0, true, true, null, new Random());
    }

    @Test(expected = IllegalArgumentException.class)
    public void testRandom_EmptyChars() {
        RandomStringUtils.random(5, 0, 0, true, true, new char[]{}, new Random());
    }

    @Test
    public void testRandom_CharsProvided_StartEndZero() {
        char[] chars = {'a', 'b', 'c'};
        // When chars != null and start/end == 0, end becomes chars.length
        String result = RandomStringUtils.random(3, 0, 0, false, false, chars, new Random());
        assertEquals(3, result.length());
        for (char c : result.toCharArray()) {
            assertTrue(c == 'a' || c == 'b' || c == 'c');
        }
    }

    @Test
    public void testRandom_NoChars_NoLettersNoNumbers_StartEndZero() {
        // end = Integer.MAX_VALUE
        String result = RandomStringUtils.random(5, 0, 0, false, false, null, new Random());
        assertEquals(5, result.length());
    }

    @Test
    public void testRandom_NoChars_LettersOrNumbers_StartEndZero() {
        // end = 'z' + 1, start = ' '
        String result = RandomStringUtils.random(5, 0, 0, true, false, null, new Random());
        assertEquals(5, result.length());
    }

    @Test
    public void testRandom_WithSpecificRange() {
        Random random = new Random();
        String result = RandomStringUtils.random(10, 'a', 'z' + 1, true, false, null, random);
        assertEquals(10, result.length());
        for (char c : result.toCharArray()) {
            assertTrue(c >= 'a' && c <= 'z');
        }
    }

    @Test
    public void testRandom_WithCharsAndFilters() {
        char[] chars = {'1', 'a', '!'};
        Random random = new Random();

        // Test numbers only
        String resNum = RandomStringUtils.random(10, 0, chars.length, false, true, chars, random);
        assertEquals(10, resNum.length());
        assertTrue(resNum.matches("[0-9]+"));

        // Test letters only
        String resLet = RandomStringUtils.random(10, 0, chars.length, true, false, chars, random);
        assertEquals(10, resLet.length());
        assertTrue(resLet.matches("[a-zA-Z]+"));

        // Test neither (only symbols)
        String resSym = RandomStringUtils.random(10, 0, chars.length, false, false, chars, random);
        assertEquals(10, resSym.length());
    }

    @Test
    public void testRandom_SurrogateHandling() {
        // We need to force the random to pick specific surrogate values to trigger branches
        // Using a Mock to control the sequence of nextInt(gap)
        // gap = end - start. Let's set start = 0, end = 10.
        // We want to return indices that map to:
        // 56320 (Low Surrogate)
        // 55296 (High Surrogate)
        // 56192 (Private High Surrogate)

        Random mockRandom = mock(Random.class);

        // Sequence of indices to return:
        // 1. 55296 (High Surrogate) -> should trigger logic to insert low surrogate before it
        // 2. 56320 (Low Surrogate) -> should trigger logic to insert high surrogate after it
        // 3. 56192 (Private High) -> should be skipped
        // 4. 'A' (Normal)

        // We'll use a custom char array containing these values
        char[] trickyChars = new char[] {
            (char)55296, // High surrogate
            (char)56320, // Low surrogate
            (char)56192, // Private high surrogate
            'A'          // Normal
        };

        // Mocking nextInt to cycle through the indices
        // Note: count-- in the loop is tricky. 
        // We need to provide enough values to satisfy the loop even when count++ happens.
        when(mockRandom.nextInt(anyInt())).thenReturn(0, 1, 2, 3, 3, 3, 3, 3, 3, 3);

        String result = RandomStringUtils.random(5, 0, trickyChars.length, false, false, trickyChars, mockRandom);

        assertNotNull(result);
        // The length might vary due to surrogate insertion, but the method returns a String from the buffer
        // The buffer size is fixed at 'count', but the logic modifies 'count' inside the loop.
        // This is a complex branch. We just ensure it doesn't crash and produces a string.
        assertFalse(result.isEmpty());
    }

    @Test
    public void testRandom_FilterLogic_AllCombinations() {
        char[] chars = {'a', '1', '$'};
        Random random = new Random();

        // letters=true, numbers=true (should include 'a' and '1')
        String res1 = RandomStringUtils.random(10, 0, chars.length, true, true, chars, random);
        assertTrue(res1.matches("[a-zA-Z0-9]+"));

        // letters=true, numbers=false (should include 'a')
        String res2 = RandomStringUtils.random(10, 0, chars.length, true, false, chars, random);
        assertTrue(res2.matches("[a-zA-Z]+"));

        // letters=false, numbers=true (should include '1')
        String res3 = RandomStringUtils.random(10, 0, chars.length, false, true, chars, random);
        assertTrue(res3.matches("[0-9]+"));

        // letters=false, numbers=false (should include '$')
        String res4 = RandomStringUtils.random(10, 0, chars.length, false, false, chars, random);
        assertTrue(res4.matches("[^a-zA-Z0-9]+"));
    }
}
